create policy "Admin inserts GSV summary" on storage.objects for insert to authenticated with check (((bucket_id='team-videos' and name='20260919-samenvatting-gecorrigeerd.mp4') or (bucket_id='team-posters' and name='gsv38-obw-20260919.jpg')) and exists(select 1 from public.app_members where user_id=(select auth.uid()) and active and role='admin'));
create policy "Admin retries GSV summary" on storage.objects for update to authenticated using (((bucket_id='team-videos' and name='20260919-samenvatting-gecorrigeerd.mp4') or (bucket_id='team-posters' and name='gsv38-obw-20260919.jpg')) and exists(select 1 from public.app_members where user_id=(select auth.uid()) and active and role='admin')) with check (((bucket_id='team-videos' and name='20260919-samenvatting-gecorrigeerd.mp4') or (bucket_id='team-posters' and name='gsv38-obw-20260919.jpg')) and exists(select 1 from public.app_members where user_id=(select auth.uid()) and active and role='admin'));
create policy "Admin publishes GSV summary" on public.team_videos for update to authenticated using (slug='gsv38-obw-20260919' and exists(select 1 from public.app_members where user_id=(select auth.uid()) and active and role='admin')) with check (slug='gsv38-obw-20260919' and exists(select 1 from public.app_members where user_id=(select auth.uid()) and active and role='admin'));
insert into public.team_videos(slug,title,description,storage_path,published) values ('gsv38-obw-20260919','GSV ’38 O17-1JM – OBW O17-1','19 september 2026 · 3–4 · Van 3–0 naar 3–4','20260919-samenvatting-gecorrigeerd.mp4',false) on conflict(slug) do nothing;
